void appendHoverText(ItemStack stack, TooltipContext context, List<Component> tooltip, TooltipFlag flag) {
        CustomData customData = stack.get(DataComponents.CUSTOM_DATA);
        int type = 1;
        String winner = "Campeón Legendario";
        String desc = "Hazaña de Campeonato";
        String date = "";

        if (customData != null) {
            CompoundTag tag = customData.copyTag();
            if (tag.contains("trophy_type")) type = tag.getInt("trophy_type");
            if (tag.contains("winner_name") && !tag.getString("winner_name").isEmpty()) winner = tag.getString("winner_name");
            if (tag.contains("achievement_desc") && !tag.getString("achievement_desc").isEmpty()) desc = tag.getString("achievement_desc");
            if (tag.contains("awarded_date")) date = tag.getString("awarded_date");
        }

        String category = switch (type) {
            case 1 -> "🏇 Gran Derby de Uma Musume";
            case 2 -> "♠️ Torneo de Blackjack High Roller";
            case 3 -> "🎰 Gran Jackpot de Casino & Ruleta";
            case 4 -> "🎱 Torneo de Billar Bola 8";
            case 5 -> "🎯 Competición de Dardos Profesional 180";
            default -> "🏆 Logro Exclusivo de Casino";
        };

        tooltip.add(Component.literal("§6✦ " + category + " ✦").withStyle(ChatFormatting.GOLD));
        tooltip.add(Component.literal("§e✦ Condecorado: §f" + winner).withStyle(ChatFormatting.YELLOW));
        tooltip.add(Component.literal("§b✦ Hazaña: §7" + desc).withStyle(ChatFormatting.AQUA));
        if (!date.isEmpty()) {
            tooltip.add(Component.literal("§8✦ Otorgado: §7" + date).withStyle(ChatFormatting.DARK_GRAY));
        }
        tooltip.add(Component.literal("§7(Colócalo en tu vitrina para admirar)").withStyle(ChatFormatting.GRAY));
    }

